#!/bin/bash
# CIFAR-100, ResNet-20, arm=diag (WCT reference arm). Writes to benchmarks/outputs/cifar100/resnet20_cifar100/diag/.
# Generated by benchmarks/slurm/generate_jobs.py — edit that file, not this one.
# See docs/reports/plan_exp_step1.md §6 and benchmarks/slurm/README.md.
# Submit from the repository root:  sbatch benchmarks/slurm/cifar100/train_resnet20_cifar100_diag.sh

#SBATCH --account=def-msh-ab
#SBATCH --job-name=resnet20_cifar100_diag
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=16G
#SBATCH --time=01:05:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

# --time: DERIVED from resnet20_cifar (MEASURED, 360.3 s).
# Dataset: cifar100, read from $DATA_ROOT (default $SLURM_SUBMIT_DIR/dataset; an ImageNet job
# overrides it with the node-local copy it stages below). Compute nodes have no internet, and
# --no-allow-download turns a missing dataset into a clear error rather than a network timeout.

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src:$SLURM_SUBMIT_DIR"
DATA_ROOT="${DATA_ROOT:-$SLURM_SUBMIT_DIR/dataset}"

# Reference arm (plan_lot8.md §0.7): a fixed 50-epoch run whose measured elapsed time is
# every other arm's wall-clock budget. Read it back from the run's manifest.json:
#   python -c "import json;print(json.load(open('benchmarks/outputs/cifar100/resnet20_cifar100/diag/manifest.json'))['arms']['diag']['total_s'])"
# and pass it to the other jobs as --wct-budget (they default to WCT_BUDGET below).
python -m benchmarks.resnet20_cifar100.bench \
  --arms diag \
  --epochs 50 \
  --budget-mode epochs \
  --num-workers 8 \
  --no-allow-download \
  --data-root "$DATA_ROOT" \
  --checkpoints 0,0.01,0.1,0.5,1 \
  --output-dir "$SLURM_SUBMIT_DIR/benchmarks/outputs/cifar100/resnet20_cifar100/diag"
